class FileLogger(object):
    """File Logger object"""

    def __init__(self, path):
        """
        "Basic initialization.
        :param path:
        """
        try:
            # self.log_file = open(path, "w")
            self.log_file = path
            self.logging = True
        except IOError:
            self.logging = False

    def log(self, data_buffer):
        """Log to file"""
        with open(self.log_file, "a") as writter:
            if self.logging:
                # self.log_file.write(data_buffer)
                writter.write(data_buffer)

    def __del__(self):
        pass
        # self.log_file.close()
